macro_rules! Timelike {
    () => {
        # [doc = " The common set of methods for time component."] pub trait Timelike : Sized { # [doc = " Returns the hour number from 0 to 23."] fn hour (& self) -> u32 ; # [doc = " Returns the hour number from 1 to 12 with a boolean flag,"] # [doc = " which is false for AM and true for PM."] # [inline] fn hour12 (& self) -> (bool , u32) { let hour = self . hour () ; let mut hour12 = hour % 12 ; if hour12 == 0 { hour12 = 12 ; } (hour >= 12 , hour12) } # [doc = " Returns the minute number from 0 to 59."] fn minute (& self) -> u32 ; # [doc = " Returns the second number from 0 to 59."] fn second (& self) -> u32 ; # [doc = " Returns the number of nanoseconds since the whole non-leap second."] # [doc = " The range from 1,000,000,000 to 1,999,999,999 represents"] # [doc = " the [leap second](./naive/struct.NaiveTime.html#leap-second-handling)."] fn nanosecond (& self) -> u32 ; # [doc = " Makes a new value with the hour number changed."] # [doc = ""] # [doc = " Returns `None` when the resulting value would be invalid."] fn with_hour (& self , hour : u32) -> Option < Self > ; # [doc = " Makes a new value with the minute number changed."] # [doc = ""] # [doc = " Returns `None` when the resulting value would be invalid."] fn with_minute (& self , min : u32) -> Option < Self > ; # [doc = " Makes a new value with the second number changed."] # [doc = ""] # [doc = " Returns `None` when the resulting value would be invalid."] # [doc = " As with the [`second`](#tymethod.second) method,"] # [doc = " the input range is restricted to 0 through 59."] fn with_second (& self , sec : u32) -> Option < Self > ; # [doc = " Makes a new value with nanoseconds since the whole non-leap second changed."] # [doc = ""] # [doc = " Returns `None` when the resulting value would be invalid."] # [doc = " As with the [`nanosecond`](#tymethod.nanosecond) method,"] # [doc = " the input range can exceed 1,000,000,000 for leap seconds."] fn with_nanosecond (& self , nano : u32) -> Option < Self > ; # [doc = " Returns the number of non-leap seconds past the last midnight."] # [doc = ""] # [doc = " Every value in 00:00:00-23:59:59 maps to an integer in 0-86399."] # [doc = ""] # [doc = " This method is not intended to provide the real number of seconds since midnight on a given"] # [doc = " day. It does not take things like DST transitions into account."] # [inline] fn num_seconds_from_midnight (& self) -> u32 { self . hour () * 3600 + self . minute () * 60 + self . second () } }
    };
}

Timelike!()